function:CREATE OR REPLACE FUNCTION __meetspace_schema__.check_direct_pair()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE ids UUID[]; cid UUID; kind TEXT; lo UUID; hi UUID; gone TIMESTAMPTZ; total BIGINT; owners BIGINT;
BEGIN
 IF TG_TABLE_NAME='conversations' THEN
  IF TG_OP='DELETE' THEN ids:=ARRAY[OLD.id]; ELSE ids:=ARRAY[NEW.id]; END IF;
 ELSIF TG_OP='INSERT' THEN ids:=ARRAY[NEW.conversation_id];
 ELSIF TG_OP='DELETE' THEN ids:=ARRAY[OLD.conversation_id];
 ELSE ids:=ARRAY[OLD.conversation_id,NEW.conversation_id]; END IF;
 FOREACH cid IN ARRAY ids LOOP
  SELECT type,user_low_id,user_high_id,deleted_at INTO kind,lo,hi,gone FROM conversations WHERE id=cid;
  IF NOT FOUND THEN CONTINUE; END IF;
  IF EXISTS(SELECT 1 FROM conversation_members m JOIN users u ON u.id=m.user_id WHERE m.conversation_id=cid AND u.guest_conference_id IS NOT NULL) THEN
   RAISE EXCEPTION 'conversation requires registered accounts' USING ERRCODE='23514';
  END IF;
  IF kind='direct' THEN
   IF (SELECT COUNT(*) FROM conversation_members WHERE conversation_id=cid)<>2
    OR EXISTS(SELECT 1 FROM conversation_members WHERE conversation_id=cid AND (user_id NOT IN(lo,hi) OR left_at IS NOT NULL OR role<>'member')) THEN
    RAISE EXCEPTION 'direct conversation requires exactly its two active registered accounts' USING ERRCODE='23514';
   END IF;
  ELSE
   SELECT count(*),count(*) FILTER(WHERE role='owner') INTO total,owners FROM conversation_members WHERE conversation_id=cid AND left_at IS NULL;
   IF total>100 OR (gone IS NULL AND (total<1 OR owners<>1)) OR (gone IS NOT NULL AND total<>0) THEN
    RAISE EXCEPTION 'active group requires one owner and at most 100 members' USING ERRCODE='23514';
   END IF;
  END IF;
 END LOOP;
 RETURN NULL;
END $function$

function:CREATE OR REPLACE FUNCTION __meetspace_schema__.enqueue_admission_notification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.user_id IS NOT NULL AND NEW.admission_decided_at IS NOT NULL AND NEW.admission_state IN ('admitted','rejected','kicked') THEN
        INSERT INTO notification_jobs(kind,entity_id,entity_version,conference_id,user_id,participant_id,admission_state,created_at)
        VALUES ('admission.decided',NEW.id,NEW.admission_version,NEW.conference_id,NEW.user_id,NEW.id,NEW.admission_state,NEW.admission_decided_at)
        ON CONFLICT(kind,entity_id,entity_version) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$function$

function:CREATE OR REPLACE FUNCTION __meetspace_schema__.enqueue_conference_integration()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE event_name TEXT;
BEGIN
 IF TG_OP='INSERT' AND NEW.status='scheduled' THEN event_name='conference.invited';
 ELSIF TG_OP='UPDATE' AND NEW.status='cancelled' AND OLD.status <> 'cancelled' THEN event_name='conference.cancelled';
 ELSIF TG_OP='UPDATE' AND NEW.status='scheduled' AND NEW.integration_version <> OLD.integration_version THEN event_name='conference.rescheduled';
 ELSE RETURN NEW; END IF;
 INSERT INTO background_jobs(kind,entity_id,conference_id,version,payload,dedup_key)
 VALUES('integrations.conference',NEW.id,NEW.id,NEW.integration_version,jsonb_build_object('event',event_name),
 'conference:'||NEW.id::text||':'||NEW.integration_version::text) ON CONFLICT(dedup_key) DO NOTHING;
 RETURN NEW;
END;
$function$

function:CREATE OR REPLACE FUNCTION __meetspace_schema__.enqueue_enrollment_integration()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF current_setting('meetrix.explicit_invitation',TRUE)='true' THEN RETURN NEW; END IF;
 IF NEW.user_id IS NOT NULL AND NEW.role <> 'owner' AND NEW.status NOT IN ('kicked','rejected') THEN
  INSERT INTO background_jobs(kind,entity_id,conference_id,user_id,version,payload,dedup_key)
  SELECT 'integrations.event',NEW.id,NEW.conference_id,NEW.user_id,c.integration_version,jsonb_build_object('event','conference.invited'),
   'enrollment:'||NEW.id::text||':'||c.integration_version::text FROM conferences c
  WHERE c.id=NEW.conference_id AND c.status='scheduled' ON CONFLICT(dedup_key) DO NOTHING;
 END IF;
 RETURN NEW;
END;
$function$

function:CREATE OR REPLACE FUNCTION __meetspace_schema__.enqueue_external_notification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.type='chat.message' THEN RETURN NEW; END IF;
 INSERT INTO background_jobs(kind,entity_id,conference_id,user_id,payload,dedup_key)
 SELECT 'integrations.delivery',NEW.id,(NEW.payload->>'conferenceId')::uuid,NEW.user_id,
 jsonb_build_object('notificationId',NEW.id,'channel',channel),
 'delivery:'||NEW.id::text||':'||channel FROM (VALUES ('email'),('push')) channels(channel)
 WHERE channel <> 'email' OR NOT (NEW.type='conference.invited' AND NEW.payload ? 'invitationId')
 ON CONFLICT(dedup_key) DO NOTHING;
 RETURN NEW;
END;
$function$

function:CREATE OR REPLACE FUNCTION __meetspace_schema__.enqueue_recording_notification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.mode IN ('composite','audio_only','individual_tracks','screen_focus') AND NEW.platform_conference_id IS NOT NULL AND NEW.status IN ('ready','partial_ready') AND NEW.deleted_at IS NULL THEN
  INSERT INTO notification_jobs(kind,entity_id,entity_version,conference_id,recording_id,created_at)
  VALUES ('recording.ready',NEW.uuid,1,NEW.platform_conference_id,NEW.uuid,NEW.updated_at)
  ON CONFLICT(kind,entity_id,entity_version) DO NOTHING;
 END IF;
 RETURN NEW;
END;
$function$

function:CREATE OR REPLACE FUNCTION __meetspace_schema__.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
	NEW.updated_at = now();
	RETURN NEW;
END;
$function$

function:CREATE OR REPLACE FUNCTION __meetspace_schema__.version_conference_integration()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.scheduled_at IS DISTINCT FROM OLD.scheduled_at OR NEW.planned_duration_min IS DISTINCT FROM OLD.planned_duration_min
 OR NEW.title IS DISTINCT FROM OLD.title OR (NEW.status='cancelled' AND OLD.status <> 'cancelled') THEN
  NEW.integration_version=OLD.integration_version+1;
  NEW.integration_version_at=clock_timestamp();
 END IF;
 RETURN NEW;
END;
$function$
